CREATE TABLE code_relationship_observations (id TEXT PRIMARY KEY, derivation_id TEXT NOT NULL REFERENCES code_derivations(id), kind TEXT NOT NULL, source_syntax_path TEXT, raw_target TEXT NOT NULL, start_byte INTEGER NOT NULL, end_byte INTEGER NOT NULL, UNIQUE(derivation_id,kind,start_byte,end_byte));
CREATE TABLE code_resolution_derivations (id TEXT PRIMARY KEY, repository_id TEXT NOT NULL REFERENCES repositories(id), commit_oid TEXT NOT NULL, resolver TEXT NOT NULL, resolver_version TEXT NOT NULL, created_at INTEGER NOT NULL, UNIQUE(repository_id,commit_oid,resolver,resolver_version));
CREATE TABLE code_relationship_resolutions (id TEXT PRIMARY KEY, resolution_derivation_id TEXT NOT NULL REFERENCES code_resolution_derivations(id), observation_id TEXT NOT NULL REFERENCES code_relationship_observations(id), state TEXT NOT NULL, target_entity_id TEXT REFERENCES code_entities(id), raw_external_target TEXT, UNIQUE(resolution_derivation_id,observation_id));
CREATE TABLE code_resolution_candidates (resolution_id TEXT NOT NULL REFERENCES code_relationship_resolutions(id), entity_id TEXT NOT NULL REFERENCES code_entities(id), PRIMARY KEY(resolution_id,entity_id));
CREATE INDEX code_relationships_by_derivation ON code_relationship_observations(derivation_id,kind);
